// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAlerts Open and recent alert incidents
	// (GET /api/alerts)
	ListAlerts(ctx context.Context, request ListAlertsRequestObject) (ListAlertsResponseObject, error)
	// GetBudget The caller's budget windows
	// (GET /api/budget)
	GetBudget(ctx context.Context, request GetBudgetRequestObject) (GetBudgetResponseObject, error)
	// DecideDevice Approve or deny a device login
	// (POST /api/device)
	DecideDevice(ctx context.Context, request DecideDeviceRequestObject) (DecideDeviceResponseObject, error)
	// StreamEvents Server-sent dashboard change events
	// (GET /api/events)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// ListKeys Device keys
	// (GET /api/keys)
	ListKeys(ctx context.Context, request ListKeysRequestObject) (ListKeysResponseObject, error)
	// RevokeKeys Revoke all active device keys of a user
	// (POST /api/keys/revoke)
	RevokeKeys(ctx context.Context, request RevokeKeysRequestObject) (RevokeKeysResponseObject, error)
	// RevokeKey Revoke a device key
	// (DELETE /api/keys/{id})
	RevokeKey(ctx context.Context, request RevokeKeyRequestObject) (RevokeKeyResponseObject, error)
	// GetMe Caller identity
	// (GET /api/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListModels Models the caller may select
	// (GET /api/models)
	ListModels(ctx context.Context, request ListModelsRequestObject) (ListModelsResponseObject, error)
	// ListConsoleOrgs The one organization, named by WRENCH_ORG_NAME
	// (GET /api/orgs)
	ListConsoleOrgs(ctx context.Context, request ListConsoleOrgsRequestObject) (ListConsoleOrgsResponseObject, error)
	// ListConsoleBudgets Budget windows as Console budget rules, for opencode's /usage
	// (GET /api/policies/current-budgets)
	ListConsoleBudgets(ctx context.Context, request ListConsoleBudgetsRequestObject) (ListConsoleBudgetsResponseObject, error)
	// ListRequests Recent attempts
	// (GET /api/requests)
	ListRequests(ctx context.Context, request ListRequestsRequestObject) (ListRequestsResponseObject, error)
	// ListSessions Recent sessions
	// (GET /api/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// GetStats Chart aggregates
	// (GET /api/stats)
	GetStats(ctx context.Context, request GetStatsRequestObject) (GetStatsResponseObject, error)
	// GetStatus Whether the caller's inference can run, and the caller's models
	// (GET /api/status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
	// GetSystem Readiness, policy, route health and accounting quality
	// (GET /api/system)
	GetSystem(ctx context.Context, request GetSystemRequestObject) (GetSystemResponseObject, error)
	// GetUsage Usage totals for the current window
	// (GET /api/usage)
	GetUsage(ctx context.Context, request GetUsageRequestObject) (GetUsageResponseObject, error)
	// GetConsoleUser The caller as an OpenCode Console account
	// (GET /api/user)
	GetConsoleUser(ctx context.Context, request GetConsoleUserRequestObject) (GetConsoleUserResponseObject, error)
	// ListUsers The allowlist with access state, limits and spend
	// (GET /api/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// RevokeUser Administrators: revoke every key and session of a user
	// (POST /api/users/{email}/revoke)
	RevokeUser(ctx context.Context, request RevokeUserRequestObject) (RevokeUserResponseObject, error)
	// GetConsoleConfig The opencode configuration for the caller
	// (GET /api/v2/config)
	GetConsoleConfig(ctx context.Context, request GetConsoleConfigRequestObject) (GetConsoleConfigResponseObject, error)
	// ListConsoleInstructions Managed instructions (none)
	// (GET /api/v2/instructions)
	ListConsoleInstructions(ctx context.Context, request ListConsoleInstructionsRequestObject) (ListConsoleInstructionsResponseObject, error)
	// ListConsoleSkills Managed skills (none yet)
	// (GET /api/v2/skills)
	ListConsoleSkills(ctx context.Context, request ListConsoleSkillsRequestObject) (ListConsoleSkillsResponseObject, error)
	// StartDeviceLogin Start a device login (RFC 8628) for opencode
	// (POST /auth/device/code)
	StartDeviceLogin(ctx context.Context, request StartDeviceLoginRequestObject) (StartDeviceLoginResponseObject, error)
	// DeviceToken Poll a device login or refresh its key
	// (POST /auth/device/token)
	DeviceToken(ctx context.Context, request DeviceTokenRequestObject) (DeviceTokenResponseObject, error)
	// GetHealthz Liveness
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz Readiness
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAlerts operation middleware
func (sh *strictHandler) ListAlerts(w http.ResponseWriter, r *http.Request, params ListAlertsParams) {
	var request ListAlertsRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAlerts(ctx, request.(ListAlertsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAlerts")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAlertsResponseObject); ok {
		if err := validResponse.VisitListAlertsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

